:root{
color-scheme:dark;--ink:#f2f1e7;--muted:#a9b5b0;--gold:#ffd278;--blue:#77a8ff;--panel:#19272a;--line:#344447}
*{
box-sizing:border-box}
body{
margin:0;min-height:100vh;background:radial-gradient(ellipse at 50% -10%,#28413e 0%,#142326 47%,#0d171a 100%);color:var(--ink);font:500 14px 'DM Sans',sans-serif;display:flex;justify-content:center;align-items:flex-start;padding:20px 14px 28px}
.shell{
width:min(1120px,100%)}
.topbar{
display:flex;justify-content:space-between;align-items:center;margin:0 auto 13px;gap:12px}
.brand{
display:flex;align-items:center;gap:11px}
.crest{
width:42px;height:42px;border-radius:13px;background:linear-gradient(145deg,#f7d77e,#d98d49);display:grid;place-items:center;color:#573c28;font-size:23px;box-shadow:0 6px 20px #0005}
.brand h1{
font:800 21px 'Outfit',sans-serif;letter-spacing:.02em;margin:0}
.brand p{
margin:1px 0 0;color:#9daea7;font-size:11px;letter-spacing:.12em;text-transform:uppercase}
.top-actions{
display:flex;gap:8px}
.btn{
border:1px solid #405352;background:#1a2a2c;color:#e3e7d9;padding:9px 13px;border-radius:10px;font:700 12px 'DM Sans';cursor:pointer;transition:.18s}
.btn:hover{
border-color:#9cbe9b;background:#253938;transform:translateY(-1px)}
.arena-frame{
background:#121e20;border:1px solid #51615a;border-radius:18px;padding:8px;box-shadow:0 24px 70px #0007;position:relative;overflow:hidden}
.canvas-wrap{
position:relative;width:100%;aspect-ratio:1000/550;border-radius:11px;overflow:hidden;background:#5d8a61}
canvas{
display:block;width:100%;height:100%;touch-action:none}
.hud{
position:absolute;inset:15px 16px auto;display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none}
.side-hud{
width:31%;display:flex;align-items:center;gap:8px}
.side-hud.enemy{
flex-direction:row-reverse;text-align:right}
.avatar{
width:34px;height:34px;flex:none;border-radius:11px;display:grid;place-items:center;font-size:17px;border:1px solid #ffffff50;background:#bb4c4a}
.avatar.you{
background:#3971ca}
.tower-meta{
min-width:0;flex:1}
.tower-name{
font:800 10px 'Outfit';letter-spacing:.1em;color:#fff;text-shadow:0 1px 4px #000;white-space:nowrap}
.hp-track{
height:7px;margin-top:4px;border:1px solid #14201cb0;background:#14201cd9;border-radius:9px;overflow:hidden}
.hp-fill{
height:100%;width:100%;background:linear-gradient(90deg,#61d078,#a4e782);border-radius:8px;transition:width .25s}
.enemy .hp-fill{
background:linear-gradient(90deg,#e9785c,#ffc269)}
.hp-label{
font-size:10px;color:#f8edcf;text-shadow:0 1px 3px #000;font-weight:800;margin-top:2px}
.timer{
background:#19272add;border:1px solid #ffffff55;box-shadow:0 3px 12px #0004;border-radius:12px;padding:6px 12px;text-align:center;min-width:66px}
.timer b{
display:block;font:800 18px 'Outfit';line-height:1}
.timer span{
font-size:9px;letter-spacing:.12em;color:#c3d0c4}
.under{
display:grid;grid-template-columns:1fr auto;gap:12px;align-items:center;padding:11px 5px 0}
.energy-box{
min-width:0}
.energy-top{
display:flex;justify-content:space-between;align-items:center;margin-bottom:6px}
.energy-title{
font:800 11px 'Outfit';letter-spacing:.11em;color:#d4cbff}
.energy-value{
font:800 13px 'Outfit';color:#e8dbff}
.energy-track{
height:10px;border-radius:8px;background:#111a21;border:1px solid #46505e;overflow:hidden;box-shadow:inset 0 2px 3px #0008}
.energy-fill{
height:100%;width:50%;background:linear-gradient(90deg,#7664de,#bd94ff);border-radius:8px;transition:width .2s}
.status{
color:#aab8ad;font-size:11px;min-width:160px;text-align:right}
.cards{
display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-top:11px}
.card{
--accent:#69a4ed;position:relative;display:grid;grid-template-columns:42px 1fr auto;align-items:center;gap:9px;text-align:left;min-width:0;border:1px solid #435355;border-radius:13px;padding:8px 10px;background:linear-gradient(145deg,#263638,#1b292b);color:var(--ink);cursor:pointer;transition:transform .16s,border-color .16s,background .16s;box-shadow:0 5px 12px #0003}
.card:hover:not(:disabled){
transform:translateY(-3px);border-color:var(--accent)}
.card.selected{
border-color:var(--accent);box-shadow:0 0 0 2px color-mix(in srgb,var(--accent) 45%,transparent),0 6px 16px #0005;background:linear-gradient(145deg,#354747,#223235)}
.card:disabled{
opacity:.48;cursor:not-allowed;filter:saturate(.6)}
.card-icon{
width:40px;height:42px;border-radius:11px;background:color-mix(in srgb,var(--accent) 25%,#182325);display:grid;place-items:center;font-size:25px;border:1px solid color-mix(in srgb,var(--accent) 55%,transparent)}
.card-name{
display:block;font:800 13px 'Outfit';white-space:nowrap}
.card-desc{
display:block;color:#9eafaa;font-size:10px;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cost{
align-self:start;display:flex;align-items:center;gap:3px;color:#e5d9ff;font:800 13px 'Outfit'}
.cost:before{
content:'✦';color:#b6a3ff;font-size:12px}
.hint{
text-align:center;color:#71827e;font-size:10px;margin:9px 0 0}
.overlay{
position:absolute;inset:0;background:#101b20b8;backdrop-filter:blur(4px);display:grid;place-items:center;z-index:3;opacity:0;pointer-events:none;transition:opacity .25s}
.overlay.show{
opacity:1;pointer-events:auto}
.result{
width:min(370px,90%);border:1px solid #687c6a;background:linear-gradient(145deg,#263a39,#172526);border-radius:20px;padding:25px;text-align:center;box-shadow:0 20px 60px #0009}
.result .medal{
font-size:42px}
.result h2{
font:900 28px 'Outfit';margin:7px 0}
.result p{
color:#b8c5bb;margin:0 0 17px}
.toast{
position:absolute;z-index:2;left:50%;top:70px;transform:translate(-50%,-8px);padding:8px 13px;border-radius:99px;background:#12201ee8;border:1px solid #ffffff38;color:#fff1ca;font-size:12px;font-weight:700;opacity:0;transition:.2s;pointer-events:none;white-space:nowrap}
.toast.show{
opacity:1;transform:translate(-50%,0)}
@media(max-width:680px){
body{
padding:10px 8px 18px}
.topbar{
margin-bottom:8px}
.brand h1{
font-size:17px}
.brand p{
font-size:9px}
.crest{
width:36px;height:36px}
.btn{
padding:8px 9px;font-size:11px}
.arena-frame{
padding:5px;border-radius:13px}
.canvas-wrap{
border-radius:9px}
.hud{
inset:8px 8px auto}
.avatar{
width:26px;height:26px;font-size:13px;border-radius:8px}
.side-hud{
gap:5px;width:34%}
.tower-name{
font-size:8px}
.hp-track{
height:5px;margin-top:3px}
.hp-label{
font-size:8px;margin-top:1px}
.timer{
min-width:51px;padding:4px 7px;border-radius:9px}
.timer b{
font-size:14px}
.timer span{
font-size:7px}
.under{
padding:8px 2px 0;gap:6px}
.status{
min-width:92px;font-size:9px}
.energy-title{
font-size:9px}
.energy-value{
font-size:11px}
.energy-track{
height:8px}
.cards{
gap:5px;margin-top:8px}
.card{
grid-template-columns:1fr;justify-items:center;gap:3px;padding:5px 3px 7px;border-radius:10px}
.card-icon{
width:31px;height:30px;font-size:20px;border-radius:8px}
.card-name{
font-size:10px}
.card-desc{
display:none}
.cost{
position:absolute;right:5px;top:4px;font-size:10px}
.hint{
font-size:9px;margin-top:7px}
}
@media(max-width:370px){
.status{
min-width:78px}
.brand p{
letter-spacing:.05em}
.btn{
padding:7px}
}

